def solve():
    n = int(input())
    a = list(map(int, input().split()))

    def is_fibonacci_ish(seq):
        if len(seq) < 2:
            return False
        for i in range(len(seq) - 2):
            if seq[i+2] != seq[i+1] + seq[i]:
                return False
        return True

    import itertools

    max_len = 0
    for perm in itertools.permutations(a):
        for i in range(2, n + 1):
            prefix = list(perm[:i])
            if is_fibonacci_ish(prefix):
                max_len = max(max_len, i)

    print(max_len)

solve()

