    commands = []
    while True:
        try:
            line = input()
            commands.append(line)
        except EOFError:
            break

    chat_members = set()
    total_traffic = 0

    for command in commands:
        if command.startswith('+'):
            name = command[1:]
            chat_members.add(name)
        elif command.startswith('-'):
